import 'package:firebase_core/firebase_core.dart';
import 'firestore_provider.dart';
import 'auth_diagnostics.dart';

class FirebaseInitializer {
  static Future<FirebaseApp> initialize() async {
    // Android options are generated by the Google Services plugin from the
    // verified android/app/google-services.json. No invented platform options.
    logAuthDiagnostic(
      AuthDiagnostic(
        event: 'firebase.initialize.start',
        request: 0,
        details: {'existingAppCount': Firebase.apps.length},
      ),
    );
    final app = Firebase.apps.isEmpty
        ? await Firebase.initializeApp()
        : Firebase.app();
    if (app.options.projectId != FirestoreProvider.projectId) {
      throw StateError('Unexpected Firebase project');
    }
    logAuthDiagnostic(
      AuthDiagnostic(
        event: 'firebase.initialize.success',
        request: 0,
        details: {
          'appName': app.name,
          'projectId': app.options.projectId,
          'appId': app.options.appId,
          'apiKeyPresent': app.options.apiKey.isNotEmpty,
        },
      ),
    );
    return app;
  }
}
